A = {0,5,7}; B = {1,3,4}; C = {6,8,10}; D = {2,9}
parts = [A,B,C,D]
given = [(0,6),(1,10),(3,6),(3,8),(2,7),(0,4),(1,6),(0,8),(1,2),(5,10),(0,3)]

def part_of(v):
    for i,p in enumerate(parts):
        if v in p: return i

# verify given edges cross parts
for u,v in given:
    assert part_of(u) != part_of(v), (u,v)

# build all edges
edges = []
for u in range(11):
    for v in range(u+1,11):
        if part_of(u) != part_of(v):
            edges.append((u,v))

# verify independence number <= 4: max independent set in complete multipartite = max part size = 3
# verify connectivity using networkx
import networkx as nx
G = nx.Graph(); G.add_nodes_from(range(11)); G.add_edges_from(edges)
print("n,m:",G.number_of_nodes(),G.number_of_edges())
print("connectivity:",nx.node_connectivity(G))
# independence number: find max independent set
from itertools import combinations
maxind=0
for k in range(5,0,-1):
    for s in combinations(range(11),k):
        ok=True
        for a,b in combinations(s,2):
            if G.has_edge(a,b): ok=False; break
        if ok:
            maxind=k; break
    if maxind: break
print("alpha:",maxind)
for e in given:
    assert G.has_edge(*e)
print(edges)
